{
  "technical_and_design_decisions": [
    "Create a new Go module github.com/hyperledger/fabric-lib-go to host externalized packages (protoutil, bccsp, msp, discovery client) similar to fabric-protos-go.",
    "Refactor statebased and entities packages to depend only on fabric-protos-go and the standard library; introduce minimal local interfaces for signing/encryption and replace flogging with the standard log package.",
    "For externalized packages, replace imports of github.com/hyperledger/fabric/protos with github.com/hyperledger/fabric-protos-go and remove fabric-internal imports by defining interfaces or moving small helpers into fabric-lib-go.",
    "Update Fabric Go SDK to consume fabric-lib-go and delete its internal copied packages.",
    "Maintain backward-compatible APIs where possible to reduce consumer impact."
  ],
  "assumptions": [
    "The fabric-lib-go module is in scope and will be created in the Hyperledger GitHub organization.",
    "Existing unit tests are adequate and will be updated during refactoring; no major new test development is required.",
    "The developer is an expert in Hyperledger Fabric and Go modules, so no learning curve is included.",
    "fabric-protos-go is already available and stable for use as the only allowed fabric dependency.",
    "U3 and U4 are addressed by editing comments and shell command examples in the marbles02_private sample only, not chaincode logic.",
    "Effort covers local build/test/dependency verification but not setting up entirely new CI infrastructure beyond existing patterns."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Refactor statebased package (U1)",
      "activity_description": "Analyze and modify core/chaincode/shim/ext/statebased to remove dependencies on fabric/comm, fabric/protoutil, common/cauthdsl, internal/pkg/identity, bccsp, msp, etc. Use only fabric-protos-go and standard lib, introducing local interfaces as needed. Update package tests and verify with 'go list' that only protos remain.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Refactor entities package (U2)",
      "activity_description": "Analyze and modify core/chaincode/shim/ext/entities/... to eliminate all fabric package imports (bccsp, factory, sw, utils, flogging, fabenc). Replace crypto with caller-provided interfaces and logging with standard log. Update tests and verify dependency closure.",
      "most_likely_effort": 50
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Fix marbles02_private sample (U3, U4)",
      "activity_description": "Update marbles02_private chaincode source comments and associated tutorial/documentation in fabric-samples to add 'tr -d \\n' (or equivalent) to base64 export commands, preventing JSON parsing errors on Windows/Ubuntu. No logic changes.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Set up fabric-lib-go module",
      "activity_description": "Create the new Go module repository skeleton for github.com/hyperledger/fabric-lib-go: go.mod, LICENSE, basic CI workflow, directory layout for protoutil, bccsp, msp, discovery.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Externalize protoutil (U5)",
      "activity_description": "Extract protoutil package into fabric-lib-go, replace fabric/protos imports with fabric-protos-go, remove dependency on internal/pkg/identity by defining minimal interfaces, preserve utility functions, and update/run tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Externalize BCCSP (U6)",
      "activity_description": "Move BCCSP and subpackages (factory, sw, signer, utils, idemix bridge as needed) into fabric-lib-go based on existing SDK copy, adjust import paths, eliminate fabric-internal dependencies, and verify build/tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Externalize MSP (U7)",
      "activity_description": "Move MSP package into fabric-lib-go, adjust imports to fabric-protos-go and fabric-lib-go internal packages, remove fabric-internal dependencies, and update tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Externalize discovery client (U8)",
      "activity_description": "Move discovery client package into fabric-lib-go, replace fabric imports with fabric-protos-go and standard gRPC, remove any fabric-internal auth dependencies, and verify tests.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Update Fabric Go SDK to use fabric-lib-go",
      "activity_description": "Modify fabric-sdk-go to import protoutil, bccsp, msp, and discovery from fabric-lib-go, delete the corresponding internal/github.com/hyperledger/fabric copies, and adjust import paths across SDK code. Run SDK tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Integration verification and dependency checks",
      "activity_description": "Perform final cross-repo build, run 'go list -f' dependency checks for statebased and entities to confirm only proto imports remain, execute unit tests for all changed packages and SDK, and fix any integration issues.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 262
  }
}

